39	function parseSession(sessionId, transcriptPath) {
40	  const lines = fs.readFileSync(transcriptPath, 'utf8').split('\n').filter(Boolean);
41	  const humanMessages = [];
42	  const agentsRun = [];
43	  const skillsRead = new Set();
44	  const corrections = [];
45	  let pendingAgent = null;
46	
47	  for (const line of lines) {
48	    let e;
49	    try { e = JSON.parse(line); } catch { continue; }
50	
51	    const role = e.message?.role;
52	    const content = e.message?.content;
53	    if (!Array.isArray(content)) continue;
54	
55	    for (const block of content) {
56	      if (role === 'user' && block.type === 'text') {
57	        const text = (block.text || '').trim();
58	        if (text.length > 2) {
59	          humanMessages.push(text.slice(0, 300));
60	          const correctionPatterns = [
61	            /\bno[,.]?\s+(don'?t|remove|stop|never|avoid)/i,
62	            /\bwrong\b/i,
63	            /\bnot like that\b/i,
64	            /\bstill\b.*\bsame\b/i,
65	            /\bagain\b/i,
66	            /\bwtf\b/i,
67	            /\bplease don'?t\b/i
68	          ];
69	          const isCorrection = correctionPatterns.some(p => p.test(text));
70	          if (isCorrection) corrections.push(text.slice(0, 200));
71	        }
72	      }
73	
74	      if (role === 'user' && block.type === 'tool_result' && pendingAgent) {
75	        const parts = Array.isArray(block.content) ? block.content : [{ type: 'text', text: String(block.content || '') }];
76	        const meta = parts.find(p => p.type === 'text' && p.text?.includes('agentId:'));
77	        if (meta) {
78	          const output = parts.filter(p => p !== meta && p.type === 'text' && p.text).map(p => p.text).join('\n').trim();
79	          agentsRun.push({
80	            type: pendingAgent.type,
81	            prompt_preview: pendingAgent.prompt,
82	            output_preview: output.slice(0, 400).replace(/\s+/g, ' '),
83	          });
84	          pendingAgent = null;
85	        }
86	      }
87	
88	      if (role === 'assistant' && block.type === 'tool_use') {
89	        if (block.name === 'Agent') {
90	          const t = (block.input?.subagent_type || 'unknown').replace(/^[^:]+:/, '').toLowerCase();
91	          pendingAgent = { type: t, prompt: (block.input?.prompt || '').slice(0, 150) };
92	        }
93	        if (block.name === 'Read') {
94	          const m = (block.input?.file_path || '').match(/skills\/([^/]+)\/SKILL\.md$/i);
95	          if (m) skillsRead.add(m[1]);
96	        }
97	      }
98	    }
99	  }
100	
101	  return {
102	    id: `sess-${Date.now()}-${crypto.randomBytes(2).toString('hex')}`,
103	    ts: new Date().toISOString(),
104	    session_id: sessionId,
105	    project: path.basename(process.cwd()),
106	    human_messages: humanMessages,
107	    corrections: corrections,
108	    agents_run: agentsRun,
109	    skills_read: [...skillsRead],
110	  };
111	}
